export const uid=()=>crypto.randomUUID();
export const clone=x=>structuredClone(x);
export const colors=['#eee5fa','#e1eee4','#f8e9c8','#f9dfd9','#e2ebf7','#ffffff','#302741'];
export const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function plain(html){if(!html)return '';const d=document.createElement('div');d.innerHTML=html||'';d.querySelectorAll('br').forEach(e=>e.replaceWith('\n'));d.querySelectorAll('p,div,li').forEach(e=>e.append('\n'));return (d.textContent||'').trim()}
export function sanitize(html){if(!html)return '';const d=document.createElement('div');d.innerHTML=html;const allowed=new Set(['DIV','P','BR','B','STRONG','I','EM','U','S','SPAN','FONT','UL','OL','LI','H1','H2','H3','PRE','CODE','SUB','SUP','MARK']);for(const n of [...d.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','IMG','AUDIO','VIDEO'].includes(n.tagName)){n.remove();continue}if(!allowed.has(n.tagName)){n.replaceWith(...n.childNodes);continue}for(const a of [...n.attributes]){if(a.name==='style'){n.setAttribute('style',a.value.split(';').filter(v=>/^\s*(color|background-color|font-family|font-size|font-weight|font-style|text-decoration|text-align)\s*:\s*[^{}<>]*$/i.test(v)&&!/(url|expression|var\s*\()/i.test(v)).join(';'))}else if(!['color','face','size'].includes(a.name))n.removeAttribute(a.name)}}return d.innerHTML}
export function node(type,x=300,y=200,opts={}){return{id:uid(),type,x,y,w:type==='text'?350:240,h:type==='text'?80:110,text:type==='code'?'const ideia = "ensinar";\nconsole.log(ideia);':type==='formula'?'E = mc^2':type==='note'?'Uma ideia para lembrar…':'Novo tópico',html:'',fill:type==='note'?'#f8e9c8':type==='text'||type==='formula'?'transparent':type==='code'?'#302741':'#eee5fa',color:type==='code'?'#eee5fa':'#302741',fontSize:type==='text'?30:18,fontFamily:'Arial',align:'left',bold:false,locked:false,hidden:false,reveal:0,shape:'rect',...opts}}
export function board(name='Novo quadro'){return{id:uid(),name,nodes:[],edges:[],strokes:[],frames:[],view:{x:100,y:80,z:.75}}}
function connect(b,a,c,label='',color='#bba7d1'){b.edges.push({id:uid(),from:a.id,to:c.id,label,color,arrow:true})}
const imageSVG=`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360" viewBox="0 0 640 360"><rect width="640" height="360" fill="#e4eee4"/><circle cx="550" cy="60" r="95" fill="#d2e2d1"/><path d="M0 300 Q180 160 370 280T640 230V360H0Z" fill="#c0d5bd"/><path d="M180 290Q310 120 500 55" fill="none" stroke="#657e61" stroke-width="7"/><ellipse cx="310" cy="147" rx="87" ry="38" transform="rotate(-36 310 147)" fill="#8faa7f"/><ellipse cx="380" cy="185" rx="75" ry="31" transform="rotate(15 380 185)" fill="#aec59f"/><ellipse cx="221" cy="225" rx="66" ry="31" transform="rotate(-48 221 225)" fill="#a0bd91"/><circle cx="102" cy="85" r="34" fill="#f4d891"/><path d="M102 35V20M102 150V135M52 85H37M167 85H152M66 49L55 38M139 122L150 133M139 49L150 38M66 122L55 133" stroke="#d2b575" stroke-width="3"/><text x="35" y="334" fill="#52694d" font-family="Arial" font-size="13" letter-spacing="3">ENERGIA QUE VIRA VIDA</text></svg>`;
export function exampleAudio(){const rate=8000,n=rate*2,buf=new ArrayBuffer(44+n*2),v=new DataView(buf);const str=(p,s)=>[...s].forEach((c,i)=>v.setUint8(p+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+n*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*2,true);for(let i=0;i<n;i++)v.setInt16(44+i*2,Math.sin(i/rate*Math.PI*2*(i<rate?440:554.37))*Math.sin(Math.PI*(i%rate)/rate)*3500,true);let s='';new Uint8Array(buf).forEach(b=>s+=String.fromCharCode(b));return 'data:audio/wav;base64,'+btoa(s)}
export function project(template='blank',name){const p={id:uid(),version:1,name:name||({example:'Fotossíntese: da luz à vida',mind:'Meu mapa mental',summary:'Resumo de aula',timeline:'Uma história em etapas',compare:'Comparando conceitos',blank:'Uma nova ideia'}[template]),updated:Date.now(),boards:[],activeBoard:0};const b=board(template==='example'?'O mapa da fotossíntese':'Visão geral');p.boards.push(b);
 if(template==='example'){
 b.nodes.push(node('text',65,28,{w:900,h:38,text:'BIOLOGIA  /  AULA 01',fontSize:13,color:'#93849f'}),node('text',65,79,{w:1000,h:77,text:'Da luz à vida.',fontSize:54,bold:true}),node('text',68,166,{w:800,h:46,text:'Como as plantas transformam energia em alimento.',fontSize:20,color:'#8e819b'}));
 const center=node('topic',490,350,{w:280,h:128,text:'Fotossíntese',fontSize:31,bold:true,fill:'#e9ddf7',align:'center'}),sun=node('topic',65,296,{w:265,h:95,text:'01   A energia do Sol',fontSize:21,fill:'#f8e9c8'}),water=node('topic',80,500,{w:250,h:100,text:'02   Água + CO₂',fontSize:22,fill:'#dfece3'}),glucose=node('topic',950,306,{w:270,h:100,text:'03   Produção de glicose',fontSize:21,fill:'#e3eaf6',reveal:1}),oxygen=node('topic',965,514,{w:255,h:95,text:'04   Liberação de O₂',fontSize:21,fill:'#f6dfd9',reveal:2});b.nodes.push(center,sun,water,glucose,oxygen);connect(b,sun,center,'absorve','#cdb578');connect(b,water,center,'utiliza','#9cb8a5');connect(b,center,glucose,'transforma','#a8b4d0');connect(b,center,oxygen,'libera','#d6aaa3');
 b.nodes.push(node('note',500,555,{w:272,h:117,text:'Pergunta para a turma\nDe onde vem a massa de uma árvore?',fontSize:17,fill:'#fff2cf'}),node('image',72,695,{w:340,h:192,src:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(imageSVG),text:'Energia que vira vida'}),node('text',463,730,{w:730,h:80,text:'Uma pequena fábrica de alimento,\nem cada folha.',fontSize:30,bold:true}));
 b.frames=[{id:uid(),name:'O mapa completo',x:0,y:0,w:1300,h:940},{id:uid(),name:'1. Luz e matéria-prima',x:35,y:240,w:820,h:470},{id:uid(),name:'2. O que a planta produz',x:455,y:250,w:830,h:470}];
 const c=board('Por dentro da folha');c.nodes.push(node('text',70,50,{w:1000,h:80,text:'Uma equação, muitas transformações.',fontSize:42,bold:true}),node('formula',120,225,{w:1050,h:150,text:'6CO_2 + 6H_2O \\xrightarrow{luz} C_6H_{12}O_6 + 6O_2',fontSize:32}),node('note',100,450,{w:440,h:180,text:'O que entra?\nÁgua, gás carbônico e energia luminosa.',fontSize:25,fill:'#dfece3'}),node('note',640,450,{w:460,h:180,text:'O que sai?\nGlicose, que armazena energia, e oxigênio.',fontSize:25,fill:'#f8e9c8'}));c.frames=[{id:uid(),name:'A equação da fotossíntese',x:0,y:0,w:1250,h:750}];p.boards.push(c);
 const d=board('Conexões e revisão');d.nodes.push(node('text',60,45,{w:1050,h:90,text:'Conecte. Explique. Lembre.',fontSize:46,bold:true}),node('text',65,180,{w:620,h:230,text:'1. Qual é a fonte de energia?\n2. Por que a água é necessária?\n3. Onde a energia fica armazenada?',fontSize:28}),node('code',730,210,{w:450,h:200,text:'// Uma analogia em código\nfunction fotossintese(luz, agua, co2) {\n  return ["glicose", "oxigênio"];\n}',fontSize:17}),node('audio',70,505,{w:430,h:120,text:'Sinal de revisão · áudio de exemplo (2 s)',src:exampleAudio(),fill:'#eee5fa'}),node('note',735,490,{w:410,h:145,text:'Experimente explicar o processo sem olhar para o mapa.',fontSize:24,fill:'#f8e9c8'}));d.strokes.push({id:uid(),points:[[74,436],[226,447],[411,438],[631,448]],color:'#bda7dc',width:8,highlight:true});d.frames=[{id:uid(),name:'Revisão e conexões',x:0,y:0,w:1250,h:750}];p.boards.push(d);
 }else if(template==='mind'){const r=node('topic',480,310,{w:260,h:120,text:'Ideia principal',fontSize:27,bold:true,align:'center'});b.nodes.push(r);['Explore','Conecte','Aprofunde','Aplique'].forEach((t,i)=>{const n=node('topic',i<2?80:950,180+(i%2)*300,{text:t,fill:colors[i+1],fontSize:24});b.nodes.push(n);connect(b,r,n)})}
 else if(template==='summary'){b.nodes.push(node('text',80,60,{text:'O essencial da aula',w:1000,h:100,fontSize:48,bold:true}),node('note',80,235,{w:335,h:300,text:'01   Ideias-chave\n\nO que precisamos entender?',fill:colors[0],fontSize:26}),node('note',450,235,{w:335,h:300,text:'02   Exemplos\n\nComo isso funciona na prática?',fill:colors[1],fontSize:26}),node('note',820,235,{w:335,h:300,text:'03   Revisão\n\nO que ficou de mais importante?',fill:colors[2],fontSize:26}))}
 else if(template==='timeline'){b.nodes.push(node('text',70,50,{text:'Uma história em etapas',w:1050,h:100,fontSize:48,bold:true}));let last;['O começo','A transformação','O resultado','O próximo passo'].forEach((t,i)=>{let n=node('topic',60+i*320,250+(i%2)*100,{text:`0${i+1}\n${t}`,w:270,h:150,fill:colors[i],fontSize:25});b.nodes.push(n);if(last)connect(b,last,n);last=n})}
 else if(template==='compare'){b.nodes.push(node('text',70,50,{text:'Duas ideias, novos olhares',w:1050,h:100,fontSize:48,bold:true}),node('note',80,235,{text:'Conceito A\n\nDefinição\nCaracterísticas\nUm exemplo',w:470,h:350,fontSize:28,fill:colors[0]}),node('note',640,235,{text:'Conceito B\n\nDefinição\nCaracterísticas\nUm exemplo',w:470,h:350,fontSize:28,fill:colors[1]}));connect(b,b.nodes[1],b.nodes[2],'O que têm em comum?')}
 return p}
export function bounds(nodes,strokes=[]){const boxes=nodes.map(n=>({x:n.x,y:n.y,w:n.w,h:n.h}));strokes.forEach(s=>{if(!s.points?.length)return;const xs=s.points.map(p=>p[0]),ys=s.points.map(p=>p[1]);boxes.push({x:Math.min(...xs)-s.width,y:Math.min(...ys)-s.width,w:Math.max(...xs)-Math.min(...xs)+2*s.width,h:Math.max(...ys)-Math.min(...ys)+2*s.width})});if(!boxes.length)return{x:0,y:0,w:1250,h:750};const x=Math.min(...boxes.map(n=>n.x)),y=Math.min(...boxes.map(n=>n.y));return{x,y,w:Math.max(...boxes.map(n=>n.x+n.w))-x,h:Math.max(...boxes.map(n=>n.y+n.h))-y}}
export function edgePoints(a,b){const ac={x:a.x+a.w/2,y:a.y+a.h/2},bc={x:b.x+b.w/2,y:b.y+b.h/2},dx=bc.x-ac.x,dy=bc.y-ac.y;if(!dx&&!dy)return[ac,bc];const r=Math.min(a.w/2/Math.max(Math.abs(dx),.01),a.h/2/Math.max(Math.abs(dy),.01)),s=Math.min(b.w/2/Math.max(Math.abs(dx),.01),b.h/2/Math.max(Math.abs(dy),.01));return[{x:ac.x+dx*r,y:ac.y+dy*r},{x:bc.x-dx*s,y:bc.y-dy*s}]}
export function validateProject(raw){if(!raw||raw.version!==1||!Array.isArray(raw.boards)||!raw.boards.length||raw.boards.length>100||typeof raw.name!=='string')throw Error('Este arquivo não é um projeto Lousa compatível.');const p=clone(raw);const safeId=x=>typeof x==="string"&&/^[a-zA-Z0-9_-]{1,100}$/.test(x);for(const b of p.boards){if(!safeId(b.id))throw Error("Identificador de quadro inválido.");for(const list of [b.nodes,b.edges,b.strokes,b.frames]){if(!Array.isArray(list))throw Error("Estrutura inválida.");for(const item of list)if(!safeId(item.id)||item.group&&!safeId(item.group))throw Error("Identificador de elemento inválido.");}}p.id=uid();p.name=p.name.slice(0,160);p.updated=Date.now();p.activeBoard=0;const num=(n,min=-1e6,max=1e6)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;const ids=new Set();for(const b of p.boards){if(!b.id||ids.has(b.id)||typeof b.name!=='string'||!Array.isArray(b.nodes)||!Array.isArray(b.edges)||!Array.isArray(b.strokes)||!Array.isArray(b.frames)||b.nodes.length>3000||b.strokes.length>15000)throw Error('Estrutura do quadro inválida.');ids.add(b.id);b.view={x:100,y:80,z:.75};const ns=new Set();for(const n of b.nodes){if(!n.id||ns.has(n.id)||!['text','topic','note','shape','image','audio','formula','code'].includes(n.type)||![n.x,n.y].every(v=>num(v))||![n.w,n.h].every(v=>num(v,.01,50000))||!num(n.fontSize,6,500))throw Error('Há um elemento inválido no projeto.');ns.add(n.id);n.text=String(n.text||'').slice(0,150000);n.html=sanitize(n.html||'');for(const c of ['fill','color'])if(n[c]!=='transparent'&&!/^#[0-9a-f]{3,8}$/i.test(n[c]||''))n[c]=c==='fill'?'#eee5fa':'#302741';n.fontFamily=['Arial','Georgia','Verdana','Trebuchet MS','Consolas'].includes(n.fontFamily)?n.fontFamily:'Arial';n.align=['left','center','right'].includes(n.align)?n.align:'left';n.reveal=num(n.reveal,0,99)?Math.floor(n.reveal):0;n.shape=['rect','ellipse','diamond'].includes(n.shape)?n.shape:'rect';n.locked=!!n.locked;n.hidden=!!n.hidden;if(['image','audio'].includes(n.type)){const pattern=n.type==='image'?/^data:image\/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/=\s]+$/:/^data:audio\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=\s]+$/i;if(!pattern.test(n.src||'')){if(n.type==='image'&&n.src==='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(imageSVG)){}else throw Error('Mídia inválida. Use imagens PNG, JPG, GIF ou WebP e áudios em formato compatível.')}}}for(const e of b.edges){if(!ns.has(e.from)||!ns.has(e.to)||e.from===e.to)throw Error('Conexão inválida.');e.label=String(e.label||'').slice(0,300);if(!/^#[0-9a-f]{3,8}$/i.test(e.color||''))e.color='#bba7d1'}for(const s of b.strokes){if(!Array.isArray(s.points)||s.points.length>50000||!s.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(v=>num(v)))||!num(s.width,1,100)||!/^#[0-9a-f]{3,8}$/i.test(s.color||''))throw Error('Desenho inválido.')}for(const f of b.frames)if(typeof f.name!=='string'||![f.x,f.y].every(v=>num(v))||![f.w,f.h].every(v=>num(v,1,1e6)))throw Error('Enquadramento inválido.')}return p}
export function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('lousa-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Feche as outras abas da Lousa e tente novamente.'))})}
export function dbAll(db){return new Promise((res,rej)=>{const tx=db.transaction('projects'),r=tx.objectStore('projects').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
export function dbWrite(db,value,del=false){return new Promise((res,rej)=>{const tx=db.transaction('projects','readwrite');const s=tx.objectStore('projects');del?s.delete(value):s.put(value);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||Error('Salvamento interrompido'))})}
